// Formata dados recebidos do LogAnalyzer AI para email
const data = items[0].json.body || items[0].json;

const severityEmoji = {
  'critical': '🔴',
  'high': '🟠',
  'medium': '🟡',
  'low': '🟢'
};

const severity = data.severity || 'low';
const emoji = severityEmoji[severity] || '⚪';

const emailSubject = emoji + ' LogAnalyzer AI - Severidade: ' + severity.toUpperCase();

const report = data.full_report || data.summary || 'Sem relatorio disponivel';

const emailBody = '<h2>' + emoji + ' Relatorio LogAnalyzer AI</h2>' +
  '<p><strong>Data:</strong> ' + (data.timestamp || 'N/A') + '</p>' +
  '<p><strong>Severidade:</strong> ' + severity.toUpperCase() + '</p>' +
  '<p><strong>Erros encontrados:</strong> ' + (data.error_count || 0) + '</p>' +
  '<p><strong>Warnings:</strong> ' + (data.warning_count || 0) + '</p>' +
  '<hr>' +
  '<h3>Relatorio Completo</h3>' +
  '<pre style="white-space: pre-wrap; font-size: 12px;">' + report + '</pre>' +
  '<hr>' +
  '<p><em>Gerado automaticamente por LogAnalyzer AI</em></p>';

return [{
  json: {
    subject: emailSubject,
    body: emailBody,
    severity: severity,
    error_count: data.error_count || 0,
    timestamp: data.timestamp || '',
    email_to: data.email_to || '',
    email_from: data.email_from || ''
  }
}];
